-- zusammenfuehrungsansatz
update public.fields set verification_status='verified_against_standard', verification_quote='Die Organisation muss die Treibhausgasemissionen und den Entzug von Treibhausgasen auf Ebene der Einrichtung nach einem der folgenden Ansätze zusammenführen: | a) Kontrolle: Die Organisation legt über alle Treibhausgasemissionen und/oder entzogenen Mengen von Treibhausgasen von Einrichtungen, über die sie die Finanzkontrolle hat oder deren Betriebsabläufe sie kontrolliert, Rechenschaft ab; | b) Beteiligung: Die Organisation legt über ihren Anteil an Treibhausgasemissionen und/oder den Entzug von Treibhausgasen von den betreffenden Einrichtungen Rechenschaft ab. | Die Organisation muss den verwendeten Ansatz zur Zusammenführung dokumentieren und darüber Bericht erstatten. — printed pp.24-25', verification_note='md-verified 2026-09-05 (§5.1 a)/b), printed pp.24-25) [VC]', verified_at=now() where id='447d8489-dc4d-4a44-ba13-0518e2354600' and verification_status not in ('verified_against_standard','corrected');
