update public.fields set verification_status='verified_against_standard', verification_quote='Das aktuelle Treibhauspotential nach IPCC sollte angewendet werden. Falls nicht, muss dies begründet werden. Der Zeitrahmen des Treibhauspotentials muss 100 Jahre betragen. Andere Treibhauspotentialzeitrahmen können verwendet werden, müssen jedoch separat angegeben werden. — printed p.29', verification_note='md-verified 2026-09-05 (§6.3, printed p.29) [VC] — SR-2: §6.3 leaves the GWP SET to an engineer choice ("sollte" IPCC, otherwise justify) but FIXES the time horizon at 100 years; that 100-year constraint is not encoded anywhere (staged)', verified_at=now() where id='b116fd28-ceef-42c4-84c4-69754df2a31d' and verification_status not in ('verified_against_standard','corrected');
-- E_co2e_total
update public.fields set verification_status='verified_against_standard', verification_quote='Die Organisation muss die Menge jeder Art von Treibhausgas unter Anwendung geeigneter Treibhauspotentiale in Tonnen $\mathrm{CO}_{2} \mathrm{AIq}$ umrechnen. | j) quantifizierte indirekte THG-Emissionen getrennt nach Kategorien in Tonnen $\mathrm{CO}_{2}$ Äq (5.2.4); — printed pp.29, 37', verification_note='md-verified 2026-09-05 (§6.3/§9.3.1 j), printed pp.29, 37) [VC] — the md transcript renders "CO2 Äq" here as the OCR artefact "\mathrm{CO}_{2} \mathrm{AIq}"; quoted verbatim as the md reads', verified_at=now() where id='b534fcea-fac6-40ec-8fab-089e00d2c1d9' and verification_status not in ('verified_against_standard','corrected');
-- entzug_thg
update public.fields set verification_status='verified_against_standard', verification_quote='Die Organisation sollte den Entzug von THG quantifizieren. | h) sofern quantifiziert, der Entzug direkter THG in Tonnen $\mathrm{CO}_{2}$ Äq (5.2.2); — printed pp.25, 37', verification_note='md-verified 2026-09-05 (§5.2.2/§9.3.1 h), printed pp.25, 37) [VC] — SOFT: §5.2.2 says "sollte" (should), so this field is correctly is_required=false', verified_at=now() where id='6b9f20ac-c228-403b-920a-ea876f21dcb1' and verification_status not in ('verified_against_standard','corrected');
-- biogen_co2
update public.fields set verification_status='verified_against_standard', verification_quote='Die Organisation muss biogene Emissionen und den biogenen Entzug nach Anhang D quantifizieren. | Anthropogene biogene $\mathrm{CO}_{2}$-Emissionen und Entzug müssen quantifiziert und getrennt von anthropogenen Emissionen angegeben werden. Anthropogene biogene Emissionen und Entzüge anderer Treibhausgase (z. B. $\mathrm{CH}_{4}$ und $\mathrm{N}_{2} \mathrm{O}$ ) müssen als anthropogen quantifiziert und angegeben werden. — printed pp.29, 71', verification_note='md-verified 2026-09-05 (§6.3/Anhang D, printed pp.29, 71) [VC] — Anhang D is NORMATIV; it makes ANTHROPOGENIC biogenic CO2 mandatory ("müssen") but NON-anthropogenic optional ("dürfen"), a distinction the single encoded field does not carry (staged)', verified_at=now() where id='6bdc6a2a-7fd0-449d-9653-89ab83034a78' and verification_status not in ('verified_against_standard','corrected');
-- strom_ansatz
update public.fields set verification_status='verified_against_standard', verification_quote='Emissionen aus importiertem elektrischem Strom, der von der Organisation eingesetzt wird, müssen von der Organisation unter Verwendung des ortsbasierten Ansatzes und Anwendung des Emissionsfaktors, der das betreffende Netz am besten charakterisiert, d.h. einer eigenen Übertragungsleitung, eines lokalen, regionalen oder nationalen netzdurchschnittlichen Emissionsfaktors, quantifiziert werden. | Bei der Verwendung von vertraglich geregelten Mitteln bei der Beschaffung ihres elektrischen Stroms darf eine Organisation den marktbasierten Ansatz anwenden, vorausgesetzt die vertraglich geregelten Mittel erfüllen die folgenden Qualitätskriterien: — printed pp.72-73', verification_note='md-verified 2026-09-05 (§E.2.1/§E.2.2, printed pp.72-73) [VC] — the ortsbasiert option is MANDATORY ("müssen"), marktbasiert is a conditional additional option ("darf ... vorausgesetzt"); the enum encodes them as equal alternatives (staged)', verified_at=now() where id='731a86e8-a228-45b9-adf7-2b810445aae0' and verification_status not in ('verified_against_standard','corrected');
-- basisjahr
update public.fields set verification_status='verified_against_standard', verification_quote='Die Organisation muss zum Vergleich der THGEmissionen und des Entzugs von Treibhausgasen oder zur Erfüllung der Anforderungen eines THGProgramms oder anderer vorgesehener Nutzungen der Treibhausgasbilanz ein historisches Basisjahr festlegen. | spezifischer historischer Zeitraum, der für den Vergleich der THG-Emissionen (3.1.5) oder des Entzugs von THG (3.1.6) oder anderer THG-bezogener Informationen über einen bestimmten Zeitraum identifiziert wurde — printed pp.30, 19', verification_note='md-verified 2026-09-05 (§6.4.1/§3.2.10, printed pp.30, 19) [VC]', verified_at=now() where id='beb67966-fe7a-4ece-b76f-7ab8aded6d94' and verification_status not in ('verified_against_standard','corrected');
-- basisjahr_bilanz
update public.fields set verification_status='verified_against_standard', verification_quote='Bei der Festlegung des Basisjahrs muss die Organisation: | a) die Treibhausgasemissionen oder entzogene Menge an Treibhausgasen für das Basisjahr unter Verwendung von Daten, die repräsentativ für die aktuelle Berichtsgrenze der Organisation sind, üblicherweise Daten von einem einzelnen Jahr, ein Mittelwert von mehreren Jahren oder ein gleitender Mittelwert, quantitativ bestimmen; | b) ein Basisjahr auswählen, für das verifizierbare Daten zu Treibhausgasemissionen oder dem Entzug von Treibhausgasen zur Verfügung stehen; — printed p.30', verification_note='md-verified 2026-09-05 (§6.4.1 a)/b), printed p.30) [VC]', verified_at=now() where id='bacea67e-743a-495a-847d-c8093a170f77' and verification_status not in ('verified_against_standard','corrected');
-- basisjahr_begruendung
update public.fields set verification_status='verified_against_standard', verification_quote='c) die Auswahl des Basisjahrs erläutern; | Die Organisation darf ihr Basisjahr ändern, sie muss jedoch jede Änderung bezüglich des Basisjahrs begründen. — printed p.30', verification_note='md-verified 2026-09-05 (§6.4.1 c), printed p.30) [VC]', verified_at=now() where id='3dc98acf-09e9-4343-baae-1f518d926d9b' and verification_status not in ('verified_against_standard','corrected');
-- neuberechnung_verfahren
update public.fields set verification_status='verified_against_standard', verification_quote='Um die Repräsentativität der basisjahrbezogenen Treibhausgasbilanz sicherzustellen, muss die Organisation eine basisjahrbezogene Prüfung und Neuberechnung entwickeln, dokumentieren und anwenden, um wesentlichen kumulativen Veränderungen der Basisjahr-Emissionen Rechnung zu tragen, die aus folgenden Faktoren entstehen: | a) einer strukturellen Veränderung der Berichtsoder Organisationsgrenzen (d. h. Fusion, Übernahme oder Auflösung), oder | b) einer Veränderung der Berechnungsmethoden oder Emissionsfaktoren, oder | c) der Aufdeckung eines Fehlers oder mehrerer kumulativer Fehler, die gemeinsam eine wesentliche Bedeutung haben. — printed p.31', verification_note='md-verified 2026-09-05 (§6.4.2 a)-c), printed p.31) [VC]', verified_at=now() where id='11db7d23-8ee3-45ed-8c79-54cef621db95' and verification_status not in ('verified_against_standard','corrected');
-- reduzierungsinitiative
update public.fields set verification_status='verified_against_standard', verification_quote='Die Organisation darf THG-Reduzierungsinitiativen planen und umsetzen, um THG-Emissionen zu reduzieren oder zu verhindern oder den Entzug von Treibhausgasen zu verbessern. | Falls eine solche Initiative umgesetzt wird, sollte die Organisation Unterschiede der THG-Emission oder des Entzugs von Treibhausgasen durch die Umsetzung von THG-Reduzierungsinitiativen quantifizieren. — printed p.31', verification_note='md-verified 2026-09-05 (§7.1, printed p.31) [VC] — SOFT: §7.1 is permissive ("darf") + recommending ("sollte"); the block gate CR-015 over this field is not supported by the source (staged)', verified_at=now() where id='d7169a25-df4e-462a-a5ee-ea5b60deee58' and verification_status not in ('verified_against_standard','corrected');
-- emissionsgutschrift
update public.fields set verification_status='verified_against_standard', verification_quote='Wenn die Organisation erworbene oder entwickelte Emissionsgutschriften in Berichten anführt, müssen die Emissionsgutschriften separat zu den THGReduzierungsinitiativen aufgelistet werden. — printed p.33', verification_note='md-verified 2026-09-05 (§7.2, printed p.33) [VC] — CONDITIONAL: the "müssen" applies only IF the organisation reports offsets; the unconditional block gate CR-016 over-enforces (staged)', verified_at=now() where id='8c79a983-d5c9-4326-810d-df91f961c618' and verification_status not in ('verified_against_standard','corrected');
-- reduzierungsziel
update public.fields set verification_status='verified_against_standard', verification_quote='Die Organisation darf Ziele für die Reduzierung von THG-Emissionen festlegen. | Wenn die Organisation ein Ziel im Bericht angibt, müssen die folgenden Informationen spezifiziert und angegeben werden: | - der Zeitraum, auf den sich das Ziel bezieht, einschließlich des Zielbezugsjahrs und des Zielabschlussjahrs; | - die Art des Ziels (Intensität oder absolut); | - im Ziel enthaltene Emissionskategorie; | - die Menge der Reduzierung und ihre Einheit in Übereinstimmung mit der Art des Ziels. — printed p.33', verification_note='md-verified 2026-09-05 (§7.3, printed p.33) [VC] — CONDITIONAL ("darf ... festlegen" / "Wenn ... angibt"); only 2 of the 4 printed items are encoded as fields (staged)', verified_at=now() where id='d8976418-ee9f-4ba3-aa8a-0ded52ab6591' and verification_status not in ('verified_against_standard','corrected');
-- zielart
update public.fields set verification_status='verified_against_standard', verification_quote='Wenn die Organisation ein Ziel im Bericht angibt, müssen die folgenden Informationen spezifiziert und angegeben werden: | - die Art des Ziels (Intensität oder absolut); — printed p.33', verification_note='md-verified 2026-09-05 (§7.3, printed p.33) [VC]', verified_at=now() where id='bff8685d-e8b3-4e78-aa70-d22a1034e9f1' and verification_status not in ('verified_against_standard','corrected');
-- info_management_verfahren
update public.fields set verification_status='verified_against_standard', verification_quote='8.1.1 Die Organisation muss Verfahren zur Verwaltung von THG-Informationen einführen und aufrechterhalten, die: | a) die Konformität mit den Grundsätzen dieses Dokuments sicherstellen; | b) mit der vorgesehenen Nutzung der Treibhausgasbilanz konsistent sind; — printed p.33', verification_note='md-verified 2026-09-05 (§8.1.1 a)/b), printed p.33) [VC] — the md German column of §8.1.1 breaks off after item b); items c)-e) survive only in the English column of the transcript', verified_at=now() where id='45944213-7bc7-46ea-94eb-ab24e490251f' and verification_status not in ('verified_against_standard','corrected');
-- dokumentenaufbewahrung
update public.fields set verification_status='verified_against_standard', verification_quote='Die Organisation muss Verfahren zur Dokumentenaufbewahrung und Pflege von Aufzeichnungen einführen und aufrechterhalten. | Die Organisation muss Dokumentationen aufbewahren und pflegen, die die Planung, Erstellung und Aufrechterhaltung der Treibhausgasbilanz belegen, um eine Verifizierung zu ermöglichen. — printed p.35', verification_note='md-verified 2026-09-05 (§8.2, printed p.35) [VC]', verified_at=now() where id='14fb18a6-94c5-4f44-a46b-bf820f9e36f6' and verification_status not in ('verified_against_standard','corrected');
-- unsicherheitsbewertung
update public.fields set verification_status='verified_against_standard', verification_quote='Die Organisation muss die Unsicherheit in Verbindung mit den Quantifizierungsansätzen (z. B. für die Quantifizierung und die Modelle verwendete Daten) bewerten und eine Bewertung durchführen, um die Unsicherheit auf der Ebene der Treibhausgasbilanzkategorie zu bestimmen. | Wenn eine quantitative Abschätzung der Unsicherheit nicht möglich oder kostenintensiv ist, muss dies begründet und eine qualitative Bewertung durchgeführt werden. — printed p.35', verification_note='md-verified 2026-09-05 (§8.3, printed p.35) [VC]', verified_at=now() where id='738de1ab-5cf3-4fcf-8a61-ac3a5973a12a' and verification_status not in ('verified_against_standard','corrected');
-- thg_bericht_erstellt
update public.fields set verification_status='verified_against_standard', verification_quote='Ein Treibhausgasbericht muss erstellt werden, wenn die Organisation ihre Treibhausgasbilanz verifizieren lassen will oder eine öffentliche THGErklärung zur Konformität mit diesem Dokument abgeben möchte. | Die Organisation sollte einen Treibhausgasbericht in Übereinstimmung mit der vorgesehenen Nutzung der Treibhausgasbilanz erstellen, um die Verifizierung der Treibhausgasbilanz zu vereinfachen. Ein Treibhausgasbericht kann z. B. erforderlich sein, um an einem THG-Programm teilzunehmen oder externe oder interne Anwender zu informieren. — printed p.35', verification_note='md-verified 2026-09-05 (§9.1, printed p.35) [VC]', verified_at=now() where id='2fb855f4-cb45-4f41-9cb1-d5a29bac7235' and verification_status not in ('verified_against_standard','corrected');
-- konformitaetserklaerung
update public.fields set verification_status='verified_against_standard', verification_quote='Der Treibhausgasbericht muss Folgendes umfassen: | r) eine Erklärung, dass der Treibhausgasbericht in Übereinstimmung mit diesem Dokument erstellt wurde; — printed pp.37-38', verification_note='md-verified 2026-09-05 (§9.3.1 r), printed pp.37-38) [VC]', verified_at=now() where id='22f1ea9e-4af3-49a8-837e-c0cab633c0ce' and verification_status not in ('verified_against_standard','corrected');
-- gwp_quelle
update public.fields set verification_status='verified_against_standard', verification_quote='t) die in der Berechnung verwendeten Treibhauspotentialwerte und ihre Quellen. Wenn die Treibhauspotentialwerte nicht aus dem aktuellen IPCC-Bericht entnommen werden, werden die Emissionsfaktoren oder die in der Berechnung verwendete Datenbasisreferenz und ihre Quelle einbezogen. — printed p.38', verification_note='md-verified 2026-09-05 (§9.3.1 t), printed p.38) [VC]', verified_at=now() where id='7a2235c1-067c-4c09-90eb-d7928f83ca10' and verification_status not in ('verified_against_standard','corrected');
-- verifizierungsart
update public.fields set verification_status='verified_against_standard', verification_quote='s) eine Offenlegung, in der beschrieben ist, ob die Treibhausgasbilanz, der Treibhausgasbericht oder die Treibhausgaserklärung verifiziert wurden, einschließlich der Art der Verifizierung und des erreichten Grads an Sicherheit; | Um die Informationen über Treibhausgasemissionen und den Entzug von Treibhausgas unparteilich und objektiv zu prüfen, muss die Organisation eine Verifizierung entsprechend den Bedürfnissen der vorgesehenen Anwender durchführen. Grundsätze und Anforderungen sind in ISO 14064-3 beschrieben. — printed pp.38, 40', verification_note='md-verified 2026-09-05 (§9.3.1 s)/§10, printed pp.38, 40) [VC]', verified_at=now() where id='d618521f-95fd-4f47-a5a6-c018578f4046' and verification_status not in ('verified_against_standard','corrected');
-- sicherheitsgrad
update public.fields set verification_status='verified_against_standard', verification_quote='s) eine Offenlegung, in der beschrieben ist, ob die Treibhausgasbilanz, der Treibhausgasbericht oder die Treibhausgaserklärung verifiziert wurden, einschließlich der Art der Verifizierung und des erreichten Grads an Sicherheit; | Grad des Vertrauens in die THG-Erklärung (3.2.5) — printed pp.38, 23', verification_note='md-verified 2026-09-05 (§9.3.1 s)/§3.4.13, printed pp.38, 23) [VC]', verified_at=now() where id='ea0fb890-9965-4b05-8483-01b2eca3ed8c' and verification_status not in ('verified_against_standard','corrected');

-- ==== equations: QUOTE BACKFILL only (verification_status already verified_against_standard; NOT touched) ====
-- Q-GHG
update public.equations set verification_quote='ANMERKUNG Verschiedene Arten von Modellen nutzen mit Emissionsfaktoren multiplizierte Aktivitätsdaten. | Die Organisation muss die Treibhausgasemissionen und den Entzug von Treibhausgasen in Übereinstimmung mit dem ausgewählten Quantifizierungsansatz berechnen (siehe 6.2). — printed p.29', verification_note=coalesce(nullif(verification_note,'') || ' | ', '') || 'md-verified 2026-09-05 (§6.2.3 ANMERKUNG/§6.3, printed p.29) [VC] — quote backfill; verification_status untouched. The standard prints NO displayed equation anywhere; "E_gas = AD * EF_gas" is EKOWAI-authored formalisation of the printed ANMERKUNG. DIMENSIONAL RESIDUE: AD[Einheit] x EF_gas[kg/Einheit] = kg, but E_gas is declared in t', verified_at=now() where id='09b790ad-bda4-4020-9ef9-9384abef9f76' and verification_quote is null;
-- Q-CAT
update public.equations set verification_quote='Anmerkung 1 zum Begriff: Das KohlendioxidÄquivalent wird berechnet, indem die Masse eines bestimmten THGs mit dessen Treibhauspotential (3.1.12) multipliziert wird. | Einheit zum Vergleich des Strahlungsantriebs eines THGs (3.1.1) mit dem von Kohlendioxid — printed p.17', verification_note=coalesce(nullif(verification_note,'') || ' | ', '') || 'md-verified 2026-09-05 (§3.1.13 Anmerkung 1, printed p.17) [VC] — quote backfill; verification_status untouched. Dimensionally consistent: t x dimensionless GWP = t CO2Aeq', verified_at=now() where id='7ac8363d-19a8-4106-94e4-c1b0abe174e2' and verification_quote is null;
-- Q-TOT
update public.equations set verification_quote='Die Organisation muss die Menge jeder Art von Treibhausgas unter Anwendung geeigneter Treibhauspotentiale in Tonnen $\mathrm{CO}_{2} \mathrm{AIq}$ umrechnen. | j) quantifizierte indirekte THG-Emissionen getrennt nach Kategorien in Tonnen $\mathrm{CO}_{2}$ Äq (5.2.4); — printed pp.29, 37', verification_note=coalesce(nullif(verification_note,'') || ' | ', '') || 'md-verified 2026-09-05 (§6.3/§9.3.1 j), printed pp.29, 37) [VC] — quote backfill; verification_status untouched. The standard prints the summation as prose, not as a formula. RESIDUE: E_el (Q-EL) is NOT an input to this sum, so imported-electricity emissions never reach E_co2e_total', verified_at=now() where id='1b725e27-bceb-438e-80cc-35ef7960d4e7' and verification_quote is null;
-- Q-EL
update public.equations set verification_quote='Emissionen aus importiertem elektrischem Strom, der von der Organisation eingesetzt wird, müssen von der Organisation unter Verwendung des ortsbasierten Ansatzes und Anwendung des Emissionsfaktors, der das betreffende Netz am besten charakterisiert, d.h. einer eigenen Übertragungsleitung, eines lokalen, regionalen oder nationalen netzdurchschnittlichen Emissionsfaktors, quantifiziert werden. | ANMERKUNG Der ortsbasierte Ansatz ist ein Verfahren zur Quantifizierung indirekter Emissionen aus Energie auf der Grundlage von durchschnittlichen Emissionsfaktoren der Energieerzeugung für festgelegte geographische Orte, einschließlich lokaler, regionaler oder nationaler Grenzen. — printed p.72', verification_note=coalesce(nullif(verification_note,'') || ' | ', '') || 'md-verified 2026-09-05 (§E.2.1, printed p.72) [VC] — quote backfill; verification_status untouched. Anhang E is NORMATIV but prints no displayed formula. DIMENSIONAL RESIDUE: EL_imp[kWh] x EF_grid[kg/kWh] = kg, but E_el is declared in t CO2Aeq', verified_at=now() where id='4e81dbbd-4211-48b7-8991-02aaf039c3e2' and verification_quote is null;
